using Microsoft.EntityFrameworkCore.Metadata;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using Microsoft.EntityFrameworkCore.Metadata.Conventions;

namespace DynamicCube.Platform.Persistence;

/// <summary>
/// All <see cref="Guid"/> primary keys are generated by the application (UUID v7), never by the database.
/// Marking them <c>ValueGeneratedNever</c> lets EF track new child entities discovered through navigations as Added.
/// </summary>
internal sealed class ClientGeneratedKeyConvention : IModelFinalizingConvention
{
    public void ProcessModelFinalizing(IConventionModelBuilder modelBuilder, IConventionContext<IConventionModelBuilder> context)
    {
        foreach (var entityType in modelBuilder.Metadata.GetEntityTypes())
        {
            var key = entityType.FindPrimaryKey();
            if (key is { Properties.Count: 1 } && key.Properties[0].ClrType == typeof(Guid))
            {
                key.Properties[0].Builder.ValueGenerated(ValueGenerated.Never);
            }
        }
    }
}
